/* ===================== BÀI 8 · Nguyên tử, electron, vật dẫn, điện môi và bán dẫn ===================== */
/* Bài 8 · Nguyên tử, electron, vật dẫn, điện môi và bán dẫn (CM01.01) — sinh bởi tools/author/maytinh/m08.py, không sửa tay.
   Phòng mô phỏng từng bước và bài tập chấm tự động; phần chữ bài học ở lesson.html (nội dung bảo vệ). */
makeMtLab(document.getElementById("lab-l8"),{id:"l8",scenarios:[{"label": "Ví dụ: Vùng năng lượng của silicon", "note": "Từ rất lạnh tới nhiệt độ phòng, rồi đặt điện áp.", "steps": [{"t": "Silicon rất lạnh: mọi electron ở vùng hóa trị", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 320 210\" role=\"img\" aria-label=\"Silicon gần 0 K: vùng dẫn trống\"><text x=\"8\" y=\"18\" class=\"sm\">Năng lượng ↑<\/text><line x1=\"30\" y1=\"200\" x2=\"30\" y2=\"26\" class=\"wire\"/><path d=\"M24 32 L30 22 L36 32\" class=\"wire\"/><rect x=\"46\" y=\"30\" width=\"164\" height=\"40\" rx=\"6\" class=\"wsoft\" stroke=\"currentColor\"/><text x=\"216\" y=\"54\" class=\"sm\">vùng dẫn<\/text><rect x=\"46\" y=\"150\" width=\"164\" height=\"40\" rx=\"6\" class=\"soft\" stroke=\"currentColor\"/><text x=\"216\" y=\"174\" class=\"sm\">vùng hóa trị<\/text><line x1=\"128\" y1=\"74\" x2=\"128\" y2=\"146\" class=\"wire\" stroke-dasharray=\"3 3\"/><text x=\"136\" y=\"114\" class=\"sm\">vùng cấm 1,12 eV (Si)<\/text><circle cx=\"60\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"60\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"79\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"79\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"98\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"98\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"117\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"117\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"136\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"136\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"155\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"155\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"174\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"174\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"193\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"193\" cy=\"178\" r=\"4\" class=\"acc\"/><\/svg>", "say": "<p>Vùng hóa trị đầy, vùng dẫn trống: không electron nào chuyển động tự do được, silicon không dẫn điện.<\/p>"}, {"t": "Nhiệt độ phòng: vài electron vượt vùng cấm", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 320 210\" role=\"img\" aria-label=\"Silicon ở nhiệt độ phòng: vài electron lên vùng dẫn, để lại lỗ trống\"><text x=\"8\" y=\"18\" class=\"sm\">Năng lượng ↑<\/text><line x1=\"30\" y1=\"200\" x2=\"30\" y2=\"26\" class=\"wire\"/><path d=\"M24 32 L30 22 L36 32\" class=\"wire\"/><rect x=\"46\" y=\"30\" width=\"164\" height=\"40\" rx=\"6\" class=\"wsoft\" stroke=\"currentColor\"/><text x=\"216\" y=\"54\" class=\"sm\">vùng dẫn<\/text><rect x=\"46\" y=\"150\" width=\"164\" height=\"40\" rx=\"6\" class=\"soft\" stroke=\"currentColor\"/><text x=\"216\" y=\"174\" class=\"sm\">vùng hóa trị<\/text><line x1=\"128\" y1=\"74\" x2=\"128\" y2=\"146\" class=\"wire\" stroke-dasharray=\"3 3\"/><text x=\"136\" y=\"114\" class=\"sm\">vùng cấm 1,12 eV (Si)<\/text><circle cx=\"60\" cy=\"162\" r=\"4\" class=\"hole\"/><circle cx=\"60\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"79\" cy=\"162\" r=\"4\" class=\"hole\"/><circle cx=\"79\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"98\" cy=\"162\" r=\"4\" class=\"hole\"/><circle cx=\"98\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"117\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"117\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"136\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"136\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"155\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"155\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"174\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"174\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"193\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"193\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"60\" cy=\"52\" r=\"4\" class=\"warm\"/><circle cx=\"79\" cy=\"52\" r=\"4\" class=\"warm\"/><circle cx=\"98\" cy=\"52\" r=\"4\" class=\"warm\"/><\/svg><p class=\"mt-calc\">Năng lượng nhiệt cỡ kT ≈ 0,026 eV ở 300 K, nhỏ hơn nhiều so với 1,12 eV → chỉ một phần rất nhỏ electron lên được<\/p>", "say": "<p>Mỗi electron lên vùng dẫn để lại một chỗ trống (vòng tròn rỗng) trong vùng hóa trị, gọi là lỗ trống (Bài 10). Chấm trong hình chỉ minh họa, không theo tỉ lệ thật.<\/p>"}, {"t": "Đặt điện áp: electron vùng dẫn chạy thành dòng (nhỏ)", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 320 210\" role=\"img\" aria-label=\"Có điện trường: electron vùng dẫn dịch chuyển\"><text x=\"8\" y=\"18\" class=\"sm\">Năng lượng ↑<\/text><line x1=\"30\" y1=\"200\" x2=\"30\" y2=\"26\" class=\"wire\"/><path d=\"M24 32 L30 22 L36 32\" class=\"wire\"/><rect x=\"46\" y=\"30\" width=\"164\" height=\"40\" rx=\"6\" class=\"wsoft\" stroke=\"currentColor\"/><text x=\"216\" y=\"54\" class=\"sm\">vùng dẫn<\/text><rect x=\"46\" y=\"150\" width=\"164\" height=\"40\" rx=\"6\" class=\"soft\" stroke=\"currentColor\"/><text x=\"216\" y=\"174\" class=\"sm\">vùng hóa trị<\/text><line x1=\"128\" y1=\"74\" x2=\"128\" y2=\"146\" class=\"wire\" stroke-dasharray=\"3 3\"/><text x=\"136\" y=\"114\" class=\"sm\">vùng cấm 1,12 eV (Si)<\/text><circle cx=\"60\" cy=\"162\" r=\"4\" class=\"hole\"/><circle cx=\"60\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"79\" cy=\"162\" r=\"4\" class=\"hole\"/><circle cx=\"79\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"98\" cy=\"162\" r=\"4\" class=\"hole\"/><circle cx=\"98\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"117\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"117\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"136\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"136\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"155\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"155\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"174\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"174\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"193\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"193\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"68\" cy=\"52\" r=\"4\" class=\"warm\"/><circle cx=\"87\" cy=\"52\" r=\"4\" class=\"warm\"/><circle cx=\"106\" cy=\"52\" r=\"4\" class=\"warm\"/><path d=\"M60 38 H196\" class=\"wire on\"/><path d=\"M190 32 L200 38 L190 44\" class=\"wire on\"/><\/svg>", "ask": {"q": "Đặt điện áp lên silicon tinh khiết ở nhiệt độ phòng. Dòng điện thế nào so với dây đồng cùng kích thước?", "o": ["Lớn hơn", "Nhỏ hơn rất nhiều", "Bằng nhau"], "a": 1}, "say": "<p>Có dòng nhưng rất nhỏ, vì số electron ở vùng dẫn ít. Điểm quý của bán dẫn: số hạt mang điện thay đổi được rất nhiều bằng nhiệt độ, ánh sáng, pha tạp chất (Bài 10) và điện trường (MOSFET, Bài 11).<\/p>"}]}, {"label": "Ví dụ: Kim loại dẫn điện ngay", "note": "Không có vùng cấm ngăn electron chuyển động.", "steps": [{"t": "Đồng: rất nhiều electron sẵn sàng chuyển động", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 320 200\" role=\"img\" aria-label=\"Kim loại: vùng năng lượng chỉ đầy một phần\"><text x=\"8\" y=\"18\" class=\"sm\">Năng lượng ↑<\/text><line x1=\"30\" y1=\"200\" x2=\"30\" y2=\"26\" class=\"wire\"/><path d=\"M24 32 L30 22 L36 32\" class=\"wire\"/><rect x=\"46\" y=\"60\" width=\"164\" height=\"120\" rx=\"6\" class=\"soft\" stroke=\"currentColor\"/><line x1=\"46\" y1=\"120\" x2=\"210\" y2=\"120\" stroke=\"currentColor\" stroke-dasharray=\"4 4\"/><text x=\"216\" y=\"95\" class=\"sm\">mức còn trống<\/text><text x=\"216\" y=\"150\" class=\"sm\">mức có electron<\/text><circle cx=\"60\" cy=\"132\" r=\"4\" class=\"acc\"/><circle cx=\"60\" cy=\"147\" r=\"4\" class=\"acc\"/><circle cx=\"60\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"79\" cy=\"132\" r=\"4\" class=\"acc\"/><circle cx=\"79\" cy=\"147\" r=\"4\" class=\"acc\"/><circle cx=\"79\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"98\" cy=\"132\" r=\"4\" class=\"acc\"/><circle cx=\"98\" cy=\"147\" r=\"4\" class=\"acc\"/><circle cx=\"98\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"117\" cy=\"132\" r=\"4\" class=\"acc\"/><circle cx=\"117\" cy=\"147\" r=\"4\" class=\"acc\"/><circle cx=\"117\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"136\" cy=\"132\" r=\"4\" class=\"acc\"/><circle cx=\"136\" cy=\"147\" r=\"4\" class=\"acc\"/><circle cx=\"136\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"155\" cy=\"132\" r=\"4\" class=\"acc\"/><circle cx=\"155\" cy=\"147\" r=\"4\" class=\"acc\"/><circle cx=\"155\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"174\" cy=\"132\" r=\"4\" class=\"acc\"/><circle cx=\"174\" cy=\"147\" r=\"4\" class=\"acc\"/><circle cx=\"174\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"193\" cy=\"132\" r=\"4\" class=\"acc\"/><circle cx=\"193\" cy=\"147\" r=\"4\" class=\"acc\"/><circle cx=\"193\" cy=\"162\" r=\"4\" class=\"acc\"/><\/svg>", "say": "<p>Trong kim loại, ngay trên các mức đã có electron còn rất nhiều mức trống sát bên, nên electron nhận chút năng lượng là chuyển động được.<\/p>"}, {"t": "Đặt điện áp: dòng lớn ngay", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 320 200\" role=\"img\" aria-label=\"Kim loại có điện trường: dòng lớn\"><text x=\"8\" y=\"18\" class=\"sm\">Năng lượng ↑<\/text><line x1=\"30\" y1=\"200\" x2=\"30\" y2=\"26\" class=\"wire\"/><path d=\"M24 32 L30 22 L36 32\" class=\"wire\"/><rect x=\"46\" y=\"60\" width=\"164\" height=\"120\" rx=\"6\" class=\"soft\" stroke=\"currentColor\"/><line x1=\"46\" y1=\"120\" x2=\"210\" y2=\"120\" stroke=\"currentColor\" stroke-dasharray=\"4 4\"/><text x=\"216\" y=\"95\" class=\"sm\">mức còn trống<\/text><text x=\"216\" y=\"150\" class=\"sm\">mức có electron<\/text><circle cx=\"60\" cy=\"132\" r=\"4\" class=\"acc\"/><circle cx=\"60\" cy=\"147\" r=\"4\" class=\"acc\"/><circle cx=\"60\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"79\" cy=\"132\" r=\"4\" class=\"acc\"/><circle cx=\"79\" cy=\"147\" r=\"4\" class=\"acc\"/><circle cx=\"79\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"98\" cy=\"132\" r=\"4\" class=\"acc\"/><circle cx=\"98\" cy=\"147\" r=\"4\" class=\"acc\"/><circle cx=\"98\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"117\" cy=\"132\" r=\"4\" class=\"acc\"/><circle cx=\"117\" cy=\"147\" r=\"4\" class=\"acc\"/><circle cx=\"117\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"136\" cy=\"132\" r=\"4\" class=\"acc\"/><circle cx=\"136\" cy=\"147\" r=\"4\" class=\"acc\"/><circle cx=\"136\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"155\" cy=\"132\" r=\"4\" class=\"acc\"/><circle cx=\"155\" cy=\"147\" r=\"4\" class=\"acc\"/><circle cx=\"155\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"174\" cy=\"132\" r=\"4\" class=\"acc\"/><circle cx=\"174\" cy=\"147\" r=\"4\" class=\"acc\"/><circle cx=\"174\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"193\" cy=\"132\" r=\"4\" class=\"acc\"/><circle cx=\"193\" cy=\"147\" r=\"4\" class=\"acc\"/><circle cx=\"193\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"66\" cy=\"112\" r=\"4\" class=\"warm\"/><circle cx=\"98\" cy=\"112\" r=\"4\" class=\"warm\"/><circle cx=\"130\" cy=\"112\" r=\"4\" class=\"warm\"/><circle cx=\"162\" cy=\"112\" r=\"4\" class=\"warm\"/><circle cx=\"194\" cy=\"112\" r=\"4\" class=\"warm\"/><path d=\"M60 100 H196\" class=\"wire on\"/><path d=\"M190 94 L200 100 L190 106\" class=\"wire on\"/><text x=\"50\" y=\"52\" class=\"sm warm\">electron dịch chuyển → có dòng<\/text><\/svg>", "ask": {"q": "Kim loại có cần năng lượng nhiệt để vượt vùng cấm mới dẫn điện không?", "o": ["Có", "Không, không có vùng cấm ngăn"], "a": 1}, "say": "<p>Đồng có điện trở suất khoảng 1,7 × 10⁻⁸ Ω·m ở nhiệt độ phòng, nên được dùng làm dây dẫn và đường mạch trên chip.<\/p>"}]}, {"label": "Ví dụ: Chất cách điện và đánh thủng", "note": "Vùng cấm rộng giữ electron ở vùng hóa trị.", "steps": [{"t": "Chất cách điện: vùng cấm rất rộng", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 320 210\" role=\"img\" aria-label=\"Chất cách điện: vùng cấm rộng\"><text x=\"8\" y=\"18\" class=\"sm\">Năng lượng ↑<\/text><line x1=\"30\" y1=\"200\" x2=\"30\" y2=\"26\" class=\"wire\"/><path d=\"M24 32 L30 22 L36 32\" class=\"wire\"/><rect x=\"46\" y=\"12\" width=\"164\" height=\"40\" rx=\"6\" class=\"wsoft\" stroke=\"currentColor\"/><text x=\"216\" y=\"36\" class=\"sm\">vùng dẫn<\/text><rect x=\"46\" y=\"172\" width=\"164\" height=\"40\" rx=\"6\" class=\"soft\" stroke=\"currentColor\"/><text x=\"216\" y=\"196\" class=\"sm\">vùng hóa trị<\/text><line x1=\"128\" y1=\"56\" x2=\"128\" y2=\"168\" class=\"wire\" stroke-dasharray=\"3 3\"/><text x=\"136\" y=\"116\" class=\"sm\">vùng cấm ≈ 9 eV (SiO₂)<\/text><circle cx=\"60\" cy=\"184\" r=\"4\" class=\"acc\"/><circle cx=\"60\" cy=\"200\" r=\"4\" class=\"acc\"/><circle cx=\"79\" cy=\"184\" r=\"4\" class=\"acc\"/><circle cx=\"79\" cy=\"200\" r=\"4\" class=\"acc\"/><circle cx=\"98\" cy=\"184\" r=\"4\" class=\"acc\"/><circle cx=\"98\" cy=\"200\" r=\"4\" class=\"acc\"/><circle cx=\"117\" cy=\"184\" r=\"4\" class=\"acc\"/><circle cx=\"117\" cy=\"200\" r=\"4\" class=\"acc\"/><circle cx=\"136\" cy=\"184\" r=\"4\" class=\"acc\"/><circle cx=\"136\" cy=\"200\" r=\"4\" class=\"acc\"/><circle cx=\"155\" cy=\"184\" r=\"4\" class=\"acc\"/><circle cx=\"155\" cy=\"200\" r=\"4\" class=\"acc\"/><circle cx=\"174\" cy=\"184\" r=\"4\" class=\"acc\"/><circle cx=\"174\" cy=\"200\" r=\"4\" class=\"acc\"/><circle cx=\"193\" cy=\"184\" r=\"4\" class=\"acc\"/><circle cx=\"193\" cy=\"200\" r=\"4\" class=\"acc\"/><\/svg>", "say": "<p>Ví dụ SiO₂ có vùng cấm khoảng 9 eV, gấp hơn 300 lần kT ở nhiệt độ phòng.<\/p>"}, {"t": "Đặt điện áp: gần như không có dòng", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 320 210\" role=\"img\" aria-label=\"Chất cách điện có điện trường: không có electron ở vùng dẫn\"><text x=\"8\" y=\"18\" class=\"sm\">Năng lượng ↑<\/text><line x1=\"30\" y1=\"200\" x2=\"30\" y2=\"26\" class=\"wire\"/><path d=\"M24 32 L30 22 L36 32\" class=\"wire\"/><rect x=\"46\" y=\"12\" width=\"164\" height=\"40\" rx=\"6\" class=\"wsoft\" stroke=\"currentColor\"/><text x=\"216\" y=\"36\" class=\"sm\">vùng dẫn<\/text><rect x=\"46\" y=\"172\" width=\"164\" height=\"40\" rx=\"6\" class=\"soft\" stroke=\"currentColor\"/><text x=\"216\" y=\"196\" class=\"sm\">vùng hóa trị<\/text><line x1=\"128\" y1=\"56\" x2=\"128\" y2=\"168\" class=\"wire\" stroke-dasharray=\"3 3\"/><text x=\"136\" y=\"116\" class=\"sm\">vùng cấm ≈ 9 eV (SiO₂)<\/text><circle cx=\"60\" cy=\"184\" r=\"4\" class=\"acc\"/><circle cx=\"60\" cy=\"200\" r=\"4\" class=\"acc\"/><circle cx=\"79\" cy=\"184\" r=\"4\" class=\"acc\"/><circle cx=\"79\" cy=\"200\" r=\"4\" class=\"acc\"/><circle cx=\"98\" cy=\"184\" r=\"4\" class=\"acc\"/><circle cx=\"98\" cy=\"200\" r=\"4\" class=\"acc\"/><circle cx=\"117\" cy=\"184\" r=\"4\" class=\"acc\"/><circle cx=\"117\" cy=\"200\" r=\"4\" class=\"acc\"/><circle cx=\"136\" cy=\"184\" r=\"4\" class=\"acc\"/><circle cx=\"136\" cy=\"200\" r=\"4\" class=\"acc\"/><circle cx=\"155\" cy=\"184\" r=\"4\" class=\"acc\"/><circle cx=\"155\" cy=\"200\" r=\"4\" class=\"acc\"/><circle cx=\"174\" cy=\"184\" r=\"4\" class=\"acc\"/><circle cx=\"174\" cy=\"200\" r=\"4\" class=\"acc\"/><circle cx=\"193\" cy=\"184\" r=\"4\" class=\"acc\"/><circle cx=\"193\" cy=\"200\" r=\"4\" class=\"acc\"/><\/svg>", "ask": {"q": "Vì sao SiO₂ gần như không dẫn điện ở nhiệt độ phòng?", "o": ["Vì không có electron", "Vì vùng cấm quá rộng, electron không lên được vùng dẫn", "Vì electron quá nặng"], "a": 1}, "say": "<p>SiO₂ có rất nhiều electron, nhưng chúng đều bị giữ ở vùng hóa trị. Đây là lý do SiO₂ dùng làm lớp cách điện trên chip (Bài 11).<\/p>"}, {"t": "Điện trường quá mạnh: đánh thủng", "html": "<p class=\"mt-calc\">Mỗi chất cách điện chỉ chịu được điện trường tới một giới hạn; vượt quá thì bị đánh thủng và dẫn điện, thường làm hỏng vĩnh viễn<\/p>", "say": "<p>Lớp cách điện trong chip rất mỏng, nên phóng tĩnh điện (ESD) từ tay người có thể đánh thủng nó. Chương 16 học cách phòng ESD.<\/p>"}]}, {"label": "Ví dụ: Nhiệt độ tăng: kim loại và bán dẫn", "note": "Điện trở suất đổi theo hai chiều ngược nhau.", "steps": [{"t": "So sánh khi nhiệt độ tăng", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">Kim loại (đồng)<\/th><th scope=\"col\">Bán dẫn tinh khiết (Si)<\/th><\/tr><\/thead><tbody><tr><td>Số electron dẫn<\/td><td>Gần như không đổi<\/td><td>Tăng rất nhanh<\/td><\/tr><tr><td>Dao động mạng tinh thể<\/td><td>Tăng, cản electron<\/td><td>Tăng<\/td><\/tr><tr><td>Điện trở suất<\/td><td class=\"new\">Tăng<\/td><td class=\"hi\">Giảm mạnh<\/td><\/tr><\/tbody><\/table>", "say": "<p>Với kim loại, số electron dẫn hầu như cố định; nhiệt chỉ làm nguyên tử dao động mạnh hơn, cản electron nhiều hơn. Với bán dẫn tinh khiết, nhiệt sinh thêm rất nhiều cặp electron – lỗ trống, nên dẫn điện tốt hơn.<\/p>"}, {"t": "Silicon lạnh: rất ít electron dẫn", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 320 210\" role=\"img\" aria-label=\"Silicon nhiệt độ thấp\"><text x=\"8\" y=\"18\" class=\"sm\">Năng lượng ↑<\/text><line x1=\"30\" y1=\"200\" x2=\"30\" y2=\"26\" class=\"wire\"/><path d=\"M24 32 L30 22 L36 32\" class=\"wire\"/><rect x=\"46\" y=\"30\" width=\"164\" height=\"40\" rx=\"6\" class=\"wsoft\" stroke=\"currentColor\"/><text x=\"216\" y=\"54\" class=\"sm\">vùng dẫn<\/text><rect x=\"46\" y=\"150\" width=\"164\" height=\"40\" rx=\"6\" class=\"soft\" stroke=\"currentColor\"/><text x=\"216\" y=\"174\" class=\"sm\">vùng hóa trị<\/text><line x1=\"128\" y1=\"74\" x2=\"128\" y2=\"146\" class=\"wire\" stroke-dasharray=\"3 3\"/><text x=\"136\" y=\"114\" class=\"sm\">vùng cấm 1,12 eV (Si)<\/text><circle cx=\"60\" cy=\"162\" r=\"4\" class=\"hole\"/><circle cx=\"60\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"79\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"79\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"98\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"98\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"117\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"117\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"136\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"136\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"155\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"155\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"174\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"174\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"193\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"193\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"60\" cy=\"52\" r=\"4\" class=\"warm\"/><\/svg>"}, {"t": "Silicon nóng hơn: nhiều electron dẫn hơn", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 320 210\" role=\"img\" aria-label=\"Silicon nhiệt độ cao\"><text x=\"8\" y=\"18\" class=\"sm\">Năng lượng ↑<\/text><line x1=\"30\" y1=\"200\" x2=\"30\" y2=\"26\" class=\"wire\"/><path d=\"M24 32 L30 22 L36 32\" class=\"wire\"/><rect x=\"46\" y=\"30\" width=\"164\" height=\"40\" rx=\"6\" class=\"wsoft\" stroke=\"currentColor\"/><text x=\"216\" y=\"54\" class=\"sm\">vùng dẫn<\/text><rect x=\"46\" y=\"150\" width=\"164\" height=\"40\" rx=\"6\" class=\"soft\" stroke=\"currentColor\"/><text x=\"216\" y=\"174\" class=\"sm\">vùng hóa trị<\/text><line x1=\"128\" y1=\"74\" x2=\"128\" y2=\"146\" class=\"wire\" stroke-dasharray=\"3 3\"/><text x=\"136\" y=\"114\" class=\"sm\">vùng cấm 1,12 eV (Si)<\/text><circle cx=\"60\" cy=\"162\" r=\"4\" class=\"hole\"/><circle cx=\"60\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"79\" cy=\"162\" r=\"4\" class=\"hole\"/><circle cx=\"79\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"98\" cy=\"162\" r=\"4\" class=\"hole\"/><circle cx=\"98\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"117\" cy=\"162\" r=\"4\" class=\"hole\"/><circle cx=\"117\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"136\" cy=\"162\" r=\"4\" class=\"hole\"/><circle cx=\"136\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"155\" cy=\"162\" r=\"4\" class=\"hole\"/><circle cx=\"155\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"174\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"174\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"193\" cy=\"162\" r=\"4\" class=\"acc\"/><circle cx=\"193\" cy=\"178\" r=\"4\" class=\"acc\"/><circle cx=\"60\" cy=\"52\" r=\"4\" class=\"warm\"/><circle cx=\"79\" cy=\"52\" r=\"4\" class=\"warm\"/><circle cx=\"98\" cy=\"52\" r=\"4\" class=\"warm\"/><circle cx=\"117\" cy=\"52\" r=\"4\" class=\"warm\"/><circle cx=\"136\" cy=\"52\" r=\"4\" class=\"warm\"/><circle cx=\"155\" cy=\"52\" r=\"4\" class=\"warm\"/><\/svg>", "ask": {"q": "Silicon tinh khiết nóng lên. Điện trở suất của nó thay đổi thế nào?", "o": ["Giảm", "Tăng", "Không đổi"], "a": 0}, "say": "<p>Đây là lý do linh kiện bán dẫn thay đổi đặc tính theo nhiệt độ, và dòng rò của chip tăng khi chip nóng (Bài 14).<\/p>"}]}, {"label": "Ví dụ: Đếm electron trong dòng 1 mA", "note": "Số electron mỗi giây = I ÷ e.", "steps": [{"t": "Dòng điện là điện tích đi qua mỗi giây", "html": "<p class=\"mt-calc\">I = Q ÷ t · 1 A = 1 C/s · điện tích một electron e ≈ 1,602 × 10⁻¹⁹ C<\/p>", "say": "<p>Ampe đo lượng điện tích đi qua tiết diện dây trong một giây.<\/p>"}, {"t": "Dòng 1 mA: số electron mỗi giây = I ÷ e", "html": "<p class=\"mt-calc\">0,001 ÷ (1,602 × 10⁻¹⁹) ≈ <b>6,24 × 10¹⁵<\/b> electron/giây<\/p>", "ask": {"q": "Dòng 1 mA tương ứng khoảng bao nhiêu electron đi qua mỗi giây?", "o": ["Khoảng 6 nghìn", "Khoảng 6,24 × 10¹⁵", "Đúng 1 000"], "a": 1}}, {"t": "Vì vậy một bit không phải một electron", "html": "<p class=\"mt-calc\">Ngay một dòng rất nhỏ cũng là hàng nghìn tỉ electron mỗi giây<\/p>", "say": "<p>Mạch số làm việc với điện áp và dòng điện, tức là hiệu ứng của rất nhiều electron. Một bit là trạng thái của cả mạch, không phải của một hạt.<\/p>"}]}, {"label": "Bẫy: Một bit có phải một nguyên tử?", "note": "Bit là khoảng điện áp được quy ước trên một mạch.", "steps": [{"t": "Một dây tín hiệu trong mạch 3,3 V", "html": "<div class=\"mt-bars\"><div><span>0 … 0,8 V<\/span><span><i class=\"\" style=\"width:53.3%\"><\/i><em>hiểu là 0<\/em><\/span><\/div><div><span>0,8 … 2,0 V<\/span><span><i class=\"e\" style=\"width:80.0%\"><\/i><em>vùng không xác định<\/em><\/span><\/div><div><span>2,0 … 3,3 V<\/span><span><i class=\"o\" style=\"width:86.7%\"><\/i><em>hiểu là 1<\/em><\/span><\/div><\/div><p class=\"mt-cap\">Ngưỡng của chuẩn logic 3,3 V phổ biến (LVTTL/LVCMOS): vào dưới 0,8 V là 0, trên 2,0 V là 1.<\/p>", "say": "<p>Bit là một <b>khoảng điện áp<\/b> được quy ước, không phải một con số chính xác. Khoảng giữa không được dùng để tránh nhầm lẫn do nhiễu.<\/p>"}, {"t": "Điện áp do điện tích trên dây và cực cổng tạo ra", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>Đầu ra cổng logic<\/b><small>nạp điện tích lên dây<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Dây + cực cổng tiếp theo<\/b><small>giữ điện tích, có điện áp<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>Cổng tiếp theo<\/b><small>đọc 0 hay 1<\/small><\/div><\/div>"}, {"t": "Kết luận: một bit = trạng thái của một mạch", "html": "<p class=\"mt-calc\">Nhiều nguyên tử, nhiều electron, nhiều transistor cùng giữ một bit<\/p>", "ask": {"q": "Câu nào đúng về một bit trong máy tính?", "o": ["Một bit là một nguyên tử", "Một bit là trạng thái của một mạch, được quy ước theo khoảng điện áp", "Một bit là một electron"], "a": 1}, "say": "<p>Giáo trình nhấn mạnh hiểu lầm này: không có “bit vật lý” là một nguyên tử. Kể cả ô nhớ nhỏ nhất cũng dùng rất nhiều nguyên tử và electron.<\/p>"}]}, {"label": "Lỗi: “Silicon dẫn điện tốt”", "note": "So điện trở suất theo cỡ độ lớn.", "steps": [{"t": "Phát biểu sai: “silicon là chất dẫn điện tốt”", "html": "<p class=\"mt-calc\">Thường nghe: chip làm bằng silicon nên silicon dẫn điện tốt<\/p>", "say": "<p>Hãy so điện trở suất.<\/p>"}, {"t": "So điện trở suất (cỡ độ lớn)", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Vật liệu<\/th><th scope=\"col\">Điện trở suất (Ω·m, cỡ độ lớn, nhiệt độ phòng)<\/th><\/tr><\/thead><tbody><tr><td>Đồng<\/td><td>1,7 × 10⁻⁸<\/td><\/tr><tr><td>Silicon tinh khiết<\/td><td>cỡ 10³ (phụ thuộc mạnh vào độ tinh khiết, nhiệt độ)<\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">10³ ÷ 10⁻⁸ = 10¹¹: silicon tinh khiết dẫn điện kém đồng khoảng trăm tỉ lần<\/p>", "ask": {"q": "Silicon tinh khiết dẫn điện kém đồng khoảng bao nhiêu lần?", "o": ["Khoảng 10 lần", "Khoảng 10¹¹ lần", "Bằng nhau"], "a": 1}}, {"t": "Sửa: silicon quý vì điều khiển được độ dẫn", "html": "<p class=\"mt-calc\">Pha tạp chất (Bài 10) có thể làm điện trở suất của silicon giảm hàng triệu lần; điện trường ở cực cổng (Bài 11) bật tắt được kênh dẫn<\/p>", "say": "<p>Giá trị của bán dẫn không phải dẫn điện tốt hay kém, mà là <b>điều khiển được<\/b> nó dẫn bao nhiêu. Dây nối trên chip vẫn làm bằng kim loại (đồng, nhôm).<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l8"),"l8",[{"kind": "pick", "t": "Phân loại vật liệu", "d": "<p>Chọn nhóm cho từng vật liệu (ở nhiệt độ phòng, không pha tạp).<\/p>", "cats": ["Vật dẫn", "Bán dẫn", "Chất cách điện (điện môi)"], "items": [{"q": "Đồng", "a": 0}, {"q": "Nhôm", "a": 0}, {"q": "Silicon tinh khiết", "a": 1}, {"q": "Germanium tinh khiết", "a": 1}, {"q": "Gali arsenua (GaAs)", "a": 1}, {"q": "Thủy tinh", "a": 2}, {"q": "Silic đioxit (SiO₂)", "a": 2}, {"q": "Sứ cách điện", "a": 2}], "hints": ["Kim loại là vật dẫn.", "Ba bán dẫn trong bài có vùng cấm từ khoảng 0,66 tới 1,42 eV.", "SiO₂ có vùng cấm khoảng 9 eV, thủy tinh và sứ cũng là chất cách điện."], "why": "Đồng, nhôm là kim loại; Si, Ge, GaAs là bán dẫn; thủy tinh, SiO₂, sứ là chất cách điện. SiO₂ còn là điện môi quan trọng trên chip."}, {"kind": "num", "t": "Electron hóa trị và vùng cấm", "d": "<p>Dùng bảng trong bài. Làm tròn 1 chữ số thập phân ở câu cuối.<\/p>", "items": [{"q": "Silicon có bao nhiêu electron hóa trị?", "a": 4}, {"q": "Phosphor có bao nhiêu electron hóa trị?", "a": 5}, {"q": "Boron có bao nhiêu electron hóa trị?", "a": 3}, {"q": "Vùng cấm của silicon (1,12 eV) gấp bao nhiêu lần kT ở 300 K (lấy kT = 0,0259 eV)?", "a": 43.24324324324325, "tol": 0.1}], "hints": ["Silicon và germanium cùng nhóm, có cùng số electron hóa trị.", "Phosphor nhiều hơn silicon một electron hóa trị, boron ít hơn một.", "Chia 1,12 cho 0,0259."], "why": "Si có 4, P có 5, B có 3 electron hóa trị. 1,12 ÷ 0,0259 ≈ 43,2: vùng cấm lớn hơn năng lượng nhiệt điển hình hàng chục lần, nên chỉ rất ít electron vượt qua được."}, {"kind": "num", "t": "Dòng điện và số electron", "d": "<p>Dùng e = 1,602 × 10⁻¹⁹ C. Làm tròn 2 chữ số thập phân.<\/p>", "items": [{"q": "Dòng 1 mA: số electron mỗi giây = ? × 10¹⁵", "a": 6.242197253433209, "tol": 0.01}, {"q": "Dòng 2 A: số electron mỗi giây = ? × 10¹⁸", "a": 12.484394506866417, "tol": 0.01}, {"q": "Điện tích 0,5 C đi qua trong 10 giây. Cường độ dòng điện bằng bao nhiêu?", "a": 0.05, "tol": 0.0001, "unit": "A"}, {"q": "Dòng 0,2 A chạy trong 1 phút. Điện tích đi qua bằng bao nhiêu?", "a": 12, "tol": 0.001, "unit": "C"}], "hints": ["Số electron mỗi giây = I ÷ e.", "1 mA = 0,001 A. 0,001 ÷ (1,602 × 10⁻¹⁹) ≈ 6,24 × 10¹⁵.", "I = Q ÷ t; Q = I × t với t tính bằng giây (1 phút = 60 s)."], "why": "0,001 ÷ 1,602 × 10⁻¹⁹ ≈ 6,24 × 10¹⁵; 2 ÷ 1,602 × 10⁻¹⁹ ≈ 12,48 × 10¹⁸; 0,5 ÷ 10 = 0,05 A; 0,2 × 60 = 12 C."}]);

makeQuiz("quiz8","score8",[{"q": "Silicon có bao nhiêu electron hóa trị?", "o": ["1", "3", "4", "14"], "a": 2, "e": "Silicon (Z = 14) có 4 electron ở lớp ngoài cùng; 14 là tổng số electron. Bốn electron hóa trị cho mỗi nguyên tử silicon 4 liên kết với 4 nguyên tử bên cạnh (Bài 10)."}, {"q": "Trong mô hình vùng năng lượng, điều gì phân biệt bán dẫn với chất cách điện?", "o": ["Bán dẫn có nhiều electron hơn", "Bán dẫn có vùng cấm hẹp hơn nên một số electron vượt qua được nhờ nhiệt", "Bán dẫn không có vùng hóa trị", "Bán dẫn luôn là kim loại"], "a": 1, "e": "Cả hai đều có vùng cấm; của bán dẫn hẹp (Si ≈ 1,12 eV), của chất cách điện rộng (SiO₂ ≈ 9 eV). Số electron không phải điểm khác biệt."}, {"q": "Silicon tinh khiết nóng lên thì điện trở suất thay đổi thế nào?", "o": ["Tăng, giống kim loại", "Không đổi", "Giảm, vì có thêm nhiều electron lên vùng dẫn", "Bằng 0"], "a": 2, "e": "Nhiệt sinh thêm cặp electron – lỗ trống nên bán dẫn tinh khiết dẫn điện tốt hơn. Kim loại thì ngược lại: điện trở suất tăng theo nhiệt độ."}, {"q": "Dòng 1 A tương ứng khoảng bao nhiêu electron đi qua tiết diện dây mỗi giây?", "o": ["6,24 × 10¹⁸", "1", "1,602 × 10⁻¹⁹", "6,24 × 10¹⁵"], "a": 0, "e": "1 ÷ (1,602 × 10⁻¹⁹) ≈ 6,24 × 10¹⁸. Đáp án 6,24 × 10¹⁵ là của dòng 1 mA."}, {"q": "Câu nào đúng về một bit trong máy tính?", "o": ["Mỗi bit được lưu bằng đúng một nguyên tử", "Mỗi bit là một electron", "Bit là trạng thái của một mạch, được quy ước theo khoảng điện áp", "Bit chỉ tồn tại trong phần mềm, không liên quan tới điện"], "a": 2, "e": "Mạch số dùng các khoảng điện áp (ví dụ dưới 0,8 V là 0, trên 2,0 V là 1 trong chuẩn 3,3 V), do rất nhiều điện tích tạo ra."}]);

